package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;
class CourseProxyTest {
 @Test void courseCreationKeyAndIndependentVersionForwardWithoutSpoofedPrincipal()throws Exception{var f=new GroupProxyTest();f.init();String base="/api/groups/"+f.id+"/courses";var r=f.request("POST",base);r.addHeader("Idempotency-Key","a".repeat(32));r.addHeader("X-Principal-Id",f.id);r.addHeader("Authorization","Bearer spoof");r.setContent("{}".getBytes());f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",base)),eq("POST"),argThat(h->h.get("Idempotency-Key").equals(List.of("a".repeat(32)))&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),any());var update=f.request("PUT",base+"/"+f.id+"/curriculum");update.addHeader("If-Match","\"co2\"");update.setContent("{\"studyIds\":[]}".getBytes());f.proxy.proxy(update);verify(f.transport).send(eq(new GatewayRoute("collaboration",base+"/"+f.id+"/curriculum")),eq("PUT"),argThat(h->h.get("If-Match").equals(List.of("\"co2\""))),any());}
 @Test void historyMaximumProtectsBoundedTransport(){var f=new GroupProxyTest();assertDoesNotThrow(f::init);String base="/api/groups/"+f.id+"/courses";for(String q:List.of("limit=6","limit=1&limit=2","actorId="+f.id)){var r=f.request("GET",base+"/"+f.id+"/revisions");r.setQueryString(q);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(r));}var missing=f.request("POST",base);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(missing));verifyNoInteractions(f.transport);}
}
